from html.parser import HTMLParser
from urllib.request import urlopen

class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.title = ''
        self.heading = ''
        self.description = ''
        self.links = []
        self.current = None
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'meta' and attrs.get('name') == 'description':
            self.description = attrs.get('content', '')
        if tag == 'a':
            self.links.append(attrs.get('href'))
        if tag in ('title', 'h1'):
            self.current = tag
    def handle_endtag(self, tag):
        if tag == self.current:
            self.current = None
    def handle_data(self, data):
        if self.current == 'title': self.title += data
        if self.current == 'h1': self.heading += data

for path in ('/', '/about'):
    with urlopen('http://localhost:3050' + path) as response:
        page = Page()
        page.feed(response.read().decode())
        print(path, response.status, repr(page.title), repr(page.description), repr(page.heading), page.links)
